from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

CENT = Decimal("0.01")


def _adj(d: Decimal) -> int:
    if d.is_zero():
        return 0
    t = d.as_tuple()
    return t.exponent + len(t.digits) - 1


def _money(value, name):
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid {name}: {value!r}") from None
    except Exception:
        raise ValueError(f"invalid {name}: {value!r}") from None
    try:
        if not amount.is_finite():
            raise ValueError(f"{name} must be finite")
    except ValueError:
        raise
    except Exception:
        raise ValueError(f"{name} must be finite") from None
    # Validate at most 2 decimal places (numerically) and quantize to cents
    # using precision sized to the input so long inputs do not raise
    # InvalidOperation under the default 28-digit context. Any failure
    # is reported as ValueError per Rule 1.
    try:
        tup = amount.as_tuple()
        adj = _adj(amount)
        prec_needed = max(28, len(tup.digits) + 10, adj + 12 if adj > 0 else 28)
        with localcontext() as ctx:
            ctx.prec = prec_needed
            # enlarge exponent range for huge magnitudes
            try:
                ctx.Emax = max(ctx.Emax, adj + 1000, prec_needed + 1000)
            except Exception:
                pass
            try:
                ctx.Emin = min(ctx.Emin, -999999999)
            except Exception:
                pass
            try:
                q = amount.quantize(CENT)
            except InvalidOperation:
                raise ValueError(f"{name} must have at most 2 decimal places") from None
            if amount != q:
                raise ValueError(f"{name} must have at most 2 decimal places")
            return q
    except ValueError:
        raise
    except InvalidOperation:
        raise ValueError(f"invalid {name}: {value!r}") from None


def _int_range(value, name, lo, hi):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{name} must be an integer")
    if not lo <= value <= hi:
        raise ValueError(f"{name} out of range")
    return value


def straight_line_schedule(cost: str, salvage: str, life_years: int, placed_year: int, placed_month: int) -> list[dict]:
    cost_d = _money(cost, "cost")
    salvage_d = _money(salvage, "salvage")
    if cost_d <= 0:
        raise ValueError("cost must be > 0")
    if salvage_d < 0 or salvage_d >= cost_d:
        raise ValueError("salvage must satisfy 0 <= salvage < cost")
    life = _int_range(life_years, "life_years", 1, 50)
    year = _int_range(placed_year, "placed_year", 1900, 2200)
    month = _int_range(placed_month, "placed_month", 1, 12)
    adj_needed = max(_adj(cost_d), _adj(salvage_d))
    prec_needed = max(50, adj_needed + 20, len(cost_d.as_tuple().digits) + 20, len(salvage_d.as_tuple().digits) + 20)
    with localcontext() as ctx:
        ctx.prec = prec_needed
        try:
            ctx.Emax = 999999999
        except Exception:
            pass
        try:
            ctx.Emin = -999999999
        except Exception:
            pass
        base = cost_d - salvage_d
        full = base / Decimal(life)
        fraction = (Decimal(12 - month) + Decimal("0.5")) / Decimal(12)
        try:
            full_quantized = full.quantize(CENT, rounding=ROUND_HALF_UP)
        except InvalidOperation:
            # With sized precision this should not happen; fall back to
            # treating full as non-zero progress if raw is non-zero.
            full_quantized = Decimal("0.01") if full > 0 else Decimal("0.00")
        rows = []
        accumulated = Decimal("0.00")
        remaining = base
        current_year = year
        first = True
        while remaining > 0:
            raw = (full * fraction) if first else full
            quantized = raw.quantize(CENT, rounding=ROUND_HALF_UP)
            if quantized >= remaining:
                amount = remaining.quantize(CENT)
            elif quantized == 0:
                # Zero quantized amount: do not sweep the whole base.
                # Emit an ordinary 0.00 row and continue to full years,
                # unless even the full annual amount quantizes to zero,
                # in which case no later year could make progress and we
                # must sweep the remainder to terminate.
                if full_quantized == 0:
                    amount = remaining.quantize(CENT)
                else:
                    amount = Decimal("0.00")
            else:
                amount = quantized
            accumulated = (accumulated + amount).quantize(CENT)
            remaining = base - accumulated
            book = (cost_d - accumulated).quantize(CENT)
            rows.append({"year": current_year, "amount": amount.quantize(CENT), "accumulated": accumulated, "book_value": book})
            current_year += 1
            first = False
        return rows
